#include <array>
#include <cstddef>
#include <iostream>
#include <optional>

/// A fixed-capacity FIFO queue.
/// TODO: document every member
template <typename T, std::size_t N>
class RingBuffer
{
public:
    bool push(const T& value)
    {
        if (m_count == N) return false;
        m_items[(m_head + m_count++) % N] = value;
        return true;
    }

    std::optional<T> pop()
    {
        if (m_count == 0) return std::nullopt;
        T v{m_items[m_head]};
        m_head = (m_head + 1) % N;
        --m_count;
        return v;
    }

private:
    std::array<T, N> m_items{};
    std::size_t m_head{}, m_count{};
};

int main()
{
    RingBuffer<int, 2> rb{};
    rb.push(1);
    std::cout << *rb.pop() << '\n';
}
